// lib/constants/sacred_3d_images.dart
import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class Sacred3DImages {
  static const String templeSanctumBase64 = '';
  static final Uint8List templeSanctumBytes = base64Decode(templeSanctumBase64);
  static Widget getTempleSanctumImage({double? width, double? height, BoxFit fit = BoxFit.cover}) => Image.memory(templeSanctumBytes, width: width, height: height, fit: fit);

  static const String karmaKalashamBase64 = '';
  static final Uint8List karmaKalashamBytes = base64Decode(karmaKalashamBase64);
  static Widget getKarmaKalashamImage({double? width, double? height, BoxFit fit = BoxFit.cover}) => Image.memory(karmaKalashamBytes, width: width, height: height, fit: fit);

  static const String bhaktiHaratiBase64 = '';
