  static Widget getJnanaGitaImage({double? width, double? height, BoxFit fit = BoxFit.cover}) => Image.memory(jnanaGitaBytes, width: width, height: height, fit: fit);

  static const String dhyanaMalaBase64 = '';
  static final Uint8List dhyanaMalaBytes = base64Decode(dhyanaMalaBase64);
  static Widget getDhyanaMalaImage({double? width, double? height, BoxFit fit = BoxFit.cover}) => Image.memory(dhyanaMalaBytes, width: width, height: height, fit: fit);

